  "loc.gpsTracker": "🛰️ GPSトラッカー",
  "loc.guide1": "アプリ <b>「Traccar Client」</b> をインストール（App Store または Google Play、無料）。",
  "loc.guide2": "アプリの <b>デバイスID</b>（Device identifier）に入力：",
  "loc.guide3": "<b>サーバーURL</b> に入力：",
  "loc.guide4": "精度 <b>中</b>、距離 <b>50 m</b>。これで移動したときだけ送信します – 静止中は送信しません。ほかの項目（間隔、ハートビート）がある場合は、ハートビートをオフまたは 0 に。",
  "loc.guide5": "位置情報へのアクセスを許可：<b>常に</b>、<b>正確な位置情報</b> をオン。",
  "loc.guide6": "<b>サービス / トラッキング</b> のスイッチをオンにし、<b>常にオンのまま</b>にします – 完了。今後はすべて pinn. で操作します：「常時送信」のオン/オフ、「1回送信」、SOS。「常時送信」がオフの間は、誰もあなたの位置を見られず、pinn. はルートを記録しません。",
  "loc.guideIntro": "ほかのアプリなしでも「📍 位置を共有」は pinn. で直接使えます – ただし pinn. を開いている間だけです。pinn. を閉じて画面がロックされていても位置が届くよう、無料アプリ「Traccar Client」が pinn. に直接送信します（Traccar サーバーは不要）。iPhone と Android で同じです。",
  "loc.h025013Watch5093": "、H02 5013、Watch 5093、Teltonika 5027。トラッカーはモバイル回線から接続するため、このポートはFRITZ!BoxでNASに転送する必要があります。",
  "loc.haveGoodTripFamily": "いってらっしゃい！家族に知らせました。",
  "loc.haveGoodTripFamily#wg": "いってらっしゃい！ルームシェアに知らせました。",
