  "loc.setupIntro": "スマホはほかに何も要りません：誰でも「自分の位置」から pinn. で直接共有できます。バックグラウンド（pinn. を閉じた状態）では、無料アプリ「Traccar Client」（iPhone・Android）が pinn. に直接送信します – Traccar サーバーは不要です。SIMカード付きのGPSトラッカー（首輪など）だけがコンテナ「traccar」を必要とします。位置情報は皆さんの NAS に残ります。",
  "loc.setupTrackersUnder": "GPSトラッカーとバックグラウンド用アプリは {btn} で設定します。",
  "loc.shareAlreadyEnded": "共有はすでに終了しています。",
  "loc.shareIntro": "家族は地図上であなたをライブで見られます。送信は移動中だけ – 静止中は送信しません。pinn. を閉じているときは、一度設定したアプリ「Traccar Client」が送信します。",
  "loc.shareIntro#wg": "ルームシェアは地図上であなたをライブで見られます。送信は移動中だけ – 静止中は送信しません。pinn. を閉じているときは、一度設定したアプリ「Traccar Client」が送信します。",
  "loc.sharedUntil": "共有中：{until}",
  "loc.sharingNotPossible": "共有できません",
  "loc.sharingOff": "共有オフ",
  "loc.shopSaved": "お店を保存しました",
  "loc.shops": "🛒 お店",
  "loc.showsWhatTraccarClient": "「Traccar Client」がpinn.に送った内容を表示します。SOSを押したあと、ここに「🆘 検知」と表示される必要があります。",
  "loc.simContainer": "SIMカード · コンテナ「traccar」",
  "loc.sosAlwaysPush": "緊急時（SOS）は家族に必ずプッシュが届きます。",
  "loc.sosAlwaysPush#wg": "緊急時（SOS）はルームシェアに必ずプッシュが届きます。",
  "loc.sosDetected": "🆘 検出",
  "loc.sosTestCreatedPush": "SOSテストを作成しました。このプロフィールではプッシュが有効ではありません",
  "loc.sosTestMe": "🆘 自分へSOSテスト",
  "loc.sosTestNotPossible": "SOSテストができません",
  "loc.sosTestSent": "SOSテストを送信しました",
  "loc.startSending": "送信を開始",
  "loc.streetTown": "通り、町",
  "loc.testSameProcessReal": "テスト：実際の助けの呼び出しと同じ流れ（プッシュ、ポップアップ、地図、住所）ですが、送信先は自分だけで、家族には気づかれません。",
  "loc.testSameProcessReal#wg": "テスト：実際の助けの呼び出しと同じ流れ（プッシュ、ポップアップ、地図、住所）ですが、送信先は自分だけで、ルームシェアには気づかれません。",
  "loc.tipSetAddressUnder": "ヒント：設定 → 自宅で住所を設定すると、場所「自宅」が自動で作られ、到着・出発のプッシュ通知が使えます。",
  "loc.traccarClientChooseSend": "「Traccar Client」で「SOSを送信」を選びます（バージョンによってアプリ内、またはアプリアイコンの長押し）。pinn.が位置、住所、時刻、通話と緊急通報{regionNotrufText}のボタン付きで、すぐに家族全員へプッシュ通知します。ヒント：緊急カードに自分の携帯番号を入力しておきましょう。",
  "loc.traccarClientChooseSend#wg": "「Traccar Client」で「SOSを送信」を選びます（バージョンによってアプリ内、またはアプリアイコンの長押し）。pinn.が位置、住所、時刻、通話と緊急通報{regionNotrufText}のボタン付きで、すぐにルームシェア全員へプッシュ通知します。ヒント：緊急カードに自分の携帯番号を入力しておきましょう。",
  "loc.traccarSetUpShownWhen": "「Traccar Client」は設定済みです – 常時送信をオンにしたときだけ表示されます。",
  "loc.trackerPorts": "GPSトラッカー（コンテナ「traccar」使用時のみ）：インターネット回線のアドレスとプロトコルごとのポート – GT06 5023 · H02 5013 · Watch 5093 · Teltonika 5027（デバイスID = IMEI）。",
  "loc.trackerViaSim": "トラッカーはSIMカード経由で NAS 上の Traccar に直接送信します – そのためコンテナ「traccar」が動いている必要があります（スマホには不要）。",
  "loc.trackersNeedContainer": "GPSトラッカーにはコンテナ「traccar」が必要です。",
