  "maint.dev.installConfirm": "プレリリース{version}を今すぐインストールしますか？不具合が含まれる可能性があり、このサーバー上のすべての家族に適用されます。事前に自動でバックアップを作成するので、「復元」からいつでも元に戻せます。pinn.は数分間利用できなくなります。",
  "maint.dev.intro": "プレリリース（GitHub上）は、完成版の前のテスト版です。通常のアップデートでは表示されません。ここで意図的に探すことができます。",
