  "maint.dev.safe": "データは失われません。インストール前にpinn.が自動でバックアップを作成します（「アップデート前」）。「復元」→「すべて」で、いつでも以前の状態に戻せます。完成版が公開されると、通常のアップデートとして案内されます。",
