  "smart.guide1": "1. 新しいショートカット「pinn Automatik」：",
  "smart.guide10": "このためには、デバイスがpinn.に接続できる必要があります（自宅のWi-FiまたはVPN）。各アクションはタスクごとに1回だけ実行されます。ボタンで開始済みのものは、オートメーションでは再度開始されません。",
  "smart.guide2": "• 「URLの内容を取得」：上のリンクを貼り付けます",
