  "smart.haTip1": "Roborock：デバイス「ロボット掃除機」を作成し、上でロボット（vacuum.…）を選ぶと、pinn.が地図から部屋を読み込みます。アクションごとに「部屋の掃除」で部屋とモード（掃除機、掃除機＋モップ、モップ）を選びます。「タスクの部屋」は家事の掃除タスクの部屋を使うため、名前はRoborockアプリと同じにしてください。",
